function distinctOrderings(nums: number[]): number[][] {
  const seen = new Set<string>();
  const out: number[][] = [];
  const used = new Array(nums.length).fill(false);
  const row: number[] = [];
  const go = (): void => {
    if (row.length === nums.length) {
      const key = row.join(",");
      if (!seen.has(key)) { seen.add(key); out.push(row.slice()); }
      return;
    }
    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue;
      used[i] = true; row.push(nums[i]);
      go();
      row.pop(); used[i] = false;
    }
  };
  go();
  return out;
}

