function distinctOrderings(nums: number[]): number[][] {
  const count = new Map<number, number>();
  for (const x of nums) count.set(x, (count.get(x) ?? 0) + 1);
  const out: number[][] = [];
  const row: number[] = [];
  const go = (): void => {
    if (row.length === nums.length) { out.push(row.slice()); return; }
    for (const [x, c] of count) {
      if (c === 0) continue;
      count.set(x, c - 1); row.push(x);
      go();
      row.pop(); count.set(x, c);
    }
  };
  go();
  return out;
}

