function distinctOrderings(nums: number[]): number[][] {
  const a = nums.slice().sort((x, y) => x - y);
  const used = new Array(a.length).fill(false);
  const out: number[][] = [];
  const row: number[] = [];
  const go = (): void => {
    if (row.length === a.length) { out.push(row.slice()); return; }
    for (let i = 0; i < a.length; i++) {
      if (used[i]) continue;
      if (i > 0 && a[i] === a[i - 1] && !used[i - 1]) continue;
      used[i] = true; row.push(a[i]);
      go();
      row.pop(); used[i] = false;
    }
  };
  go();
  return out;
}

